let authority = Pubkey::new_unique();
let treasury_key = Pubkey::new_unique();

let treasury_data = anchor_account_data("Treasury", &(authority, 1000u64, true));

let treasury_legit = account(&env.program_id, &treasury_data, None);
let authority_acc = wallet(1_000_000_000);
let (system_id, system_acc) = system_program_account();

let init_ix = env.anchor_ix(
    "initialize",
    &(1000u64,),
    vec![
        AccountMeta::new(treasury_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(system_id, false),
    ],
);

let init_accounts = vec![
    (treasury_key, empty_account()),
    (authority, authority_acc.clone()),
    (system_id, system_acc.clone()),
];

let baseline = env.baseline("initialize legitimo", &init_ix, &init_accounts);

let forged_owner = Pubkey::new_unique();
let forged_treasury = account(&forged_owner, &treasury_data, None);

let attack_ix = env.anchor_ix(
    "process",
    &(),
    vec![
        AccountMeta::new_readonly(treasury_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);

let attack_accounts = vec![
    (treasury_key, forged_treasury),
    (authority, authority_acc),
];

let r = env.attack("process com conta forjada", &attack_ix, &attack_accounts);

if r.program_result == ProgramResult::Success {
    let used = after(&r, &treasury_key);
    env.effect(
        "conta forjada com dono diferente foi aceita",
        used.owner() != &env.program_id,
    );
}
